mapper.select:
SELECT * FROM bohe_bill
WHERE user_id = #{userId}

ORDER BY bill_date DESC, id DESC

mapper.update:
UPDATE bohe_bill
SET amount = #{amount}, category = #{category}, note = #{note}, bill_date = #{billDate}, create_time = #{createTime}
WHERE cloud_id = #{cloudId}

mapper.select:
SELECT * FROM bohe_friend
WHERE user_id = #{userId} OR friend_id = #{userId}
AND status = #{status}
ORDER BY update_time DESC
